def equations_possible(equations):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        parent[find(a)] = find(b)

    # First pass: merge every equality into the same equivalence class.
    for eq in equations:
        if eq[1] == '=':
            union(eq[0], eq[3])
    # Second pass: only after all merges, verify inequalities.
    for eq in equations:
        if eq[1] == '!':
            if find(eq[0]) == find(eq[3]):
                return False
    return True
